QUESTIONS = [
{"q":"How many flights are currently in the system?","sql":"SELECT COUNT(*) FROM flights;","difficulty":"easy","category":"simple filtering"},
{"q":"Which airline had the highest cancellation rate?","sql":"SELECT al.airline_name, ROUND(100.0*SUM(CASE WHEN f.status='Cancelled' THEN 1 ELSE 0 END)/COUNT(*),2) AS cancel_rate FROM flights f JOIN airlines al ON f.airline_id=al.airline_id GROUP BY al.airline_id ORDER BY cancel_rate DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"List all passengers with Platinum frequent flyer status.","sql":"SELECT first_name, last_name, nationality FROM passengers WHERE frequent_flyer_tier = 'Platinum';","difficulty":"easy","category":"simple filtering"},
{"q":"Which airline transported the highest number of passengers based on confirmed bookings?","sql":"SELECT al.airline_name, COUNT(*) AS passengers_transported FROM bookings b JOIN flights f ON b.flight_id=f.flight_id JOIN airlines al ON f.airline_id=al.airline_id WHERE b.booking_status='Confirmed' GROUP BY al.airline_id ORDER BY passengers_transported DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"What is the average fare amount by seat class?","sql":"SELECT seat_class, ROUND(AVG(fare_amount),2) AS avg_fare FROM bookings GROUP BY seat_class ORDER BY avg_fare DESC;","difficulty":"easy","category":"aggregation"},
{"q":"How many distinct passengers have flown with SkyBridge Airlines?","sql":"SELECT COUNT(DISTINCT b.passenger_id) FROM bookings b JOIN flights f ON b.flight_id=f.flight_id JOIN airlines al ON f.airline_id=al.airline_id WHERE al.airline_name='SkyBridge Airlines';","difficulty":"medium","category":"COUNT DISTINCT"},
{"q":"Which airports have the most departing flights?","sql":"SELECT ap.city, ap.airport_code, COUNT(*) AS departures FROM flights f JOIN airports ap ON f.origin_airport_id=ap.airport_id GROUP BY ap.airport_id ORDER BY departures DESC LIMIT 5;","difficulty":"medium","category":"GROUP BY"},
{"q":"List passengers who have made more than 8 bookings.","sql":"SELECT p.first_name, p.last_name, COUNT(*) AS num_bookings FROM bookings b JOIN passengers p ON b.passenger_id=p.passenger_id GROUP BY p.passenger_id HAVING COUNT(*) > 8 ORDER BY num_bookings DESC;","difficulty":"medium","category":"HAVING"},
{"q":"What is the total revenue generated from Business class bookings?","sql":"SELECT ROUND(SUM(fare_amount),2) AS total_revenue FROM bookings WHERE seat_class='Business' AND booking_status='Confirmed';","difficulty":"easy","category":"aggregation"},
{"q":"Which aircraft model is used most frequently across all airlines?","sql":"SELECT model, COUNT(*) AS num_aircraft FROM aircraft GROUP BY model ORDER BY num_aircraft DESC LIMIT 1;","difficulty":"easy","category":"GROUP BY"},
{"q":"Find flights that were delayed departing from JFK.","sql":"SELECT f.flight_number, f.departure_time, f.status FROM flights f JOIN airports ap ON f.origin_airport_id=ap.airport_id WHERE ap.airport_code='JFK' AND f.status='Delayed';","difficulty":"easy","category":"JOIN"},
{"q":"How many bookings have no associated fare amount recorded?","sql":"SELECT COUNT(*) FROM bookings WHERE fare_amount IS NULL;","difficulty":"easy","category":"NULL handling"},
{"q":"Which passengers have flown on more than 3 different airlines?","sql":"SELECT p.first_name, p.last_name, COUNT(DISTINCT f.airline_id) AS num_airlines FROM bookings b JOIN passengers p ON b.passenger_id=p.passenger_id JOIN flights f ON b.flight_id=f.flight_id GROUP BY p.passenger_id HAVING COUNT(DISTINCT f.airline_id) > 3;","difficulty":"hard","category":"HAVING"},
{"q":"What is the average flight duration in hours for each airline?","sql":"SELECT al.airline_name, ROUND(AVG((julianday(f.arrival_time)-julianday(f.departure_time))*24),2) AS avg_duration_hrs FROM flights f JOIN airlines al ON f.airline_id=al.airline_id GROUP BY al.airline_id ORDER BY avg_duration_hrs DESC;","difficulty":"hard","category":"date functions"},
{"q":"List the 5 most recent bookings made.","sql":"SELECT booking_id, passenger_id, booking_date, seat_class FROM bookings ORDER BY booking_date DESC LIMIT 5;","difficulty":"easy","category":"LIMIT"},
{"q":"Which flights had zero confirmed bookings?","sql":"SELECT f.flight_id, f.flight_number FROM flights f WHERE f.flight_id NOT IN (SELECT flight_id FROM bookings WHERE booking_status='Confirmed');","difficulty":"medium","category":"nested queries"},
{"q":"What is the total number of aircraft owned by each airline?","sql":"SELECT al.airline_name, COUNT(*) AS num_aircraft FROM aircraft ac JOIN airlines al ON ac.airline_id=al.airline_id GROUP BY al.airline_id ORDER BY num_aircraft DESC;","difficulty":"easy","category":"GROUP BY"},
{"q":"Find passengers who booked flights but whose booking was later cancelled more than once.","sql":"SELECT p.first_name, p.last_name, COUNT(*) AS cancelled_count FROM bookings b JOIN passengers p ON b.passenger_id=p.passenger_id WHERE b.booking_status='Cancelled' GROUP BY p.passenger_id HAVING COUNT(*) > 1 ORDER BY cancelled_count DESC;","difficulty":"medium","category":"HAVING"},
{"q":"What percentage of all flights were completed on schedule (status Completed)?","sql":"SELECT ROUND(100.0*SUM(CASE WHEN status='Completed' THEN 1 ELSE 0 END)/COUNT(*),2) AS completed_pct FROM flights;","difficulty":"medium","category":"aggregation"},
{"q":"Which route (origin-destination pair) has the highest number of flights?","sql":"SELECT o.airport_code AS origin, d.airport_code AS destination, COUNT(*) AS num_flights FROM flights f JOIN airports o ON f.origin_airport_id=o.airport_id JOIN airports d ON f.destination_airport_id=d.airport_id GROUP BY f.origin_airport_id, f.destination_airport_id ORDER BY num_flights DESC LIMIT 1;","difficulty":"hard","category":"multiple joins"},
{"q":"How many passengers have never made a booking?","sql":"SELECT COUNT(*) FROM passengers WHERE passenger_id NOT IN (SELECT DISTINCT passenger_id FROM bookings);","difficulty":"medium","category":"nested queries"},
{"q":"List airlines founded before 1980.","sql":"SELECT airline_name, founded_year FROM airlines WHERE founded_year < 1980 ORDER BY founded_year;","difficulty":"easy","category":"simple filtering"},
{"q":"What is the average fare paid by passengers with Gold status versus those with no status?","sql":"SELECT p.frequent_flyer_tier, ROUND(AVG(b.fare_amount),2) AS avg_fare FROM bookings b JOIN passengers p ON b.passenger_id=p.passenger_id WHERE p.frequent_flyer_tier IN ('Gold','None') GROUP BY p.frequent_flyer_tier;","difficulty":"medium","category":"GROUP BY"},
{"q":"Which aircraft has flown the most flights?","sql":"SELECT ac.aircraft_id, ac.model, COUNT(*) AS num_flights FROM flights f JOIN aircraft ac ON f.aircraft_id=ac.aircraft_id GROUP BY ac.aircraft_id ORDER BY num_flights DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"Find the total fare revenue collected per month over the last year.","sql":"SELECT strftime('%Y-%m', booking_date) AS month, ROUND(SUM(fare_amount),2) AS revenue FROM bookings WHERE booking_status='Confirmed' GROUP BY month ORDER BY month;","difficulty":"hard","category":"date functions"},
{"q":"Which passengers have booked both Economy and First class seats?","sql":"SELECT p.first_name, p.last_name FROM passengers p WHERE p.passenger_id IN (SELECT passenger_id FROM bookings WHERE seat_class='Economy') AND p.passenger_id IN (SELECT passenger_id FROM bookings WHERE seat_class='First');","difficulty":"hard","category":"nested queries"},
{"q":"What is the capacity utilization estimate (confirmed bookings vs aircraft capacity) for each flight, top 10 highest?","sql":"SELECT f.flight_number, COUNT(b.booking_id) AS confirmed_bookings, ac.capacity, ROUND(100.0*COUNT(b.booking_id)/ac.capacity,2) AS utilization_pct FROM flights f JOIN aircraft ac ON f.aircraft_id=ac.aircraft_id LEFT JOIN bookings b ON f.flight_id=b.flight_id AND b.booking_status='Confirmed' GROUP BY f.flight_id ORDER BY utilization_pct DESC LIMIT 10;","difficulty":"hard","category":"multiple joins"},
{"q":"Which country has the most airlines headquartered there?","sql":"SELECT country, COUNT(*) AS num_airlines FROM airlines GROUP BY country ORDER BY num_airlines DESC LIMIT 1;","difficulty":"easy","category":"GROUP BY"},
{"q":"List flights arriving at Dubai international airport (DXB).","sql":"SELECT f.flight_number, f.arrival_time, f.status FROM flights f JOIN airports ap ON f.destination_airport_id=ap.airport_id WHERE ap.airport_code='DXB';","difficulty":"easy","category":"JOIN"},
{"q":"Which passenger has spent the most money on bookings in total?","sql":"SELECT p.first_name, p.last_name, ROUND(SUM(b.fare_amount),2) AS total_spent FROM bookings b JOIN passengers p ON b.passenger_id=p.passenger_id WHERE b.booking_status='Confirmed' GROUP BY p.passenger_id ORDER BY total_spent DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"How many aircraft were manufactured after 2018?","sql":"SELECT COUNT(*) FROM aircraft WHERE manufacture_year > 2018;","difficulty":"easy","category":"simple filtering"},
{"q":"Find airlines whose average booking fare exceeds the overall average fare across all airlines.","sql":"SELECT al.airline_name, ROUND(AVG(b.fare_amount),2) AS avg_fare FROM bookings b JOIN flights f ON b.flight_id=f.flight_id JOIN airlines al ON f.airline_id=al.airline_id GROUP BY al.airline_id HAVING AVG(b.fare_amount) > (SELECT AVG(fare_amount) FROM bookings);","difficulty":"hard","category":"correlated subqueries"},
{"q":"What is the busiest month for flight departures?","sql":"SELECT strftime('%Y-%m', departure_time) AS month, COUNT(*) AS num_departures FROM flights GROUP BY month ORDER BY num_departures DESC LIMIT 1;","difficulty":"medium","category":"date functions"},
{"q":"List passengers born before 1960.","sql":"SELECT first_name, last_name, birth_date FROM passengers WHERE birth_date < '1960-01-01';","difficulty":"easy","category":"simple filtering"},
{"q":"Which flights have a duration longer than 10 hours?","sql":"SELECT flight_number, departure_time, arrival_time, ROUND((julianday(arrival_time)-julianday(departure_time))*24,2) AS duration_hrs FROM flights WHERE (julianday(arrival_time)-julianday(departure_time))*24 > 10 ORDER BY duration_hrs DESC;","difficulty":"medium","category":"date functions"},
{"q":"How many waitlisted bookings currently exist per airline?","sql":"SELECT al.airline_name, COUNT(*) AS waitlisted FROM bookings b JOIN flights f ON b.flight_id=f.flight_id JOIN airlines al ON f.airline_id=al.airline_id WHERE b.booking_status='Waitlisted' GROUP BY al.airline_id ORDER BY waitlisted DESC;","difficulty":"medium","category":"GROUP BY"},
{"q":"Which nationality of passengers books the most Business class seats?","sql":"SELECT p.nationality, COUNT(*) AS business_bookings FROM bookings b JOIN passengers p ON b.passenger_id=p.passenger_id WHERE b.seat_class='Business' GROUP BY p.nationality ORDER BY business_bookings DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"Find the second-highest fare ever paid for a single booking.","sql":"SELECT fare_amount FROM bookings ORDER BY fare_amount DESC LIMIT 1 OFFSET 1;","difficulty":"medium","category":"LIMIT"},
{"q":"How many distinct routes does each airline operate?","sql":"SELECT al.airline_name, COUNT(DISTINCT f.origin_airport_id || '-' || f.destination_airport_id) AS distinct_routes FROM flights f JOIN airlines al ON f.airline_id=al.airline_id GROUP BY al.airline_id ORDER BY distinct_routes DESC;","difficulty":"hard","category":"COUNT DISTINCT"},
{"q":"Which flights are scheduled but originate from an airport with fewer than 20 total flights?","sql":"SELECT f.flight_number, f.origin_airport_id FROM flights f WHERE f.status='Scheduled' AND f.origin_airport_id IN (SELECT origin_airport_id FROM flights GROUP BY origin_airport_id HAVING COUNT(*) < 20);","difficulty":"hard","category":"correlated subqueries"},
{"q":"What is the total number of seats (capacity) available across all aircraft owned by each airline?","sql":"SELECT al.airline_name, SUM(ac.capacity) AS total_capacity FROM aircraft ac JOIN airlines al ON ac.airline_id=al.airline_id GROUP BY al.airline_id ORDER BY total_capacity DESC;","difficulty":"medium","category":"aggregation"},
{"q":"List bookings made on the same day the flight departed (same-day bookings).","sql":"SELECT b.booking_id, b.booking_date, f.departure_time FROM bookings b JOIN flights f ON b.flight_id=f.flight_id WHERE date(b.booking_date) = date(f.departure_time) LIMIT 20;","difficulty":"medium","category":"date functions"},
{"q":"Which passengers have a booking with a NULL or missing seat class recorded?","sql":"SELECT DISTINCT p.first_name, p.last_name FROM passengers p JOIN bookings b ON p.passenger_id=b.passenger_id WHERE b.seat_class IS NULL;","difficulty":"easy","category":"NULL handling"},
{"q":"What is the average passenger age at time of booking, grouped by seat class?","sql":"SELECT b.seat_class, ROUND(AVG((julianday(b.booking_date)-julianday(p.birth_date))/365.25),1) AS avg_age FROM bookings b JOIN passengers p ON b.passenger_id=p.passenger_id GROUP BY b.seat_class ORDER BY avg_age DESC;","difficulty":"hard","category":"date functions"},
{"q":"Which airline operates the newest fleet on average (by manufacture year)?","sql":"SELECT al.airline_name, ROUND(AVG(ac.manufacture_year),1) AS avg_year FROM aircraft ac JOIN airlines al ON ac.airline_id=al.airline_id GROUP BY al.airline_id ORDER BY avg_year DESC LIMIT 1;","difficulty":"medium","category":"aggregation"},
{"q":"How many flights were delayed or cancelled in the last 90 days?","sql":"SELECT COUNT(*) FROM flights WHERE status IN ('Delayed','Cancelled') AND departure_time >= date('now','-90 day');","difficulty":"medium","category":"date functions"},
{"q":"Find the top 3 passengers by number of distinct destination cities visited.","sql":"SELECT p.first_name, p.last_name, COUNT(DISTINCT ap.city) AS distinct_cities FROM bookings b JOIN passengers p ON b.passenger_id=p.passenger_id JOIN flights f ON b.flight_id=f.flight_id JOIN airports ap ON f.destination_airport_id=ap.airport_id WHERE b.booking_status='Confirmed' GROUP BY p.passenger_id ORDER BY distinct_cities DESC LIMIT 3;","difficulty":"hard","category":"multiple joins"},
{"q":"What is the total number of bookings in the system?","sql":"SELECT COUNT(*) FROM bookings;","difficulty":"easy","category":"simple filtering"},
{"q":"Which airports serve as both an origin and destination for more than 50 flights combined?","sql":"SELECT ap.airport_code, ap.city, (SELECT COUNT(*) FROM flights WHERE origin_airport_id=ap.airport_id) + (SELECT COUNT(*) FROM flights WHERE destination_airport_id=ap.airport_id) AS total_traffic FROM airports ap HAVING total_traffic > 50 ORDER BY total_traffic DESC;","difficulty":"hard","category":"correlated subqueries"},
]
